tool_input.command:
python3 - <<'EOF'
p='escrow.ts'; s=open(p).read()
s=s.replace('''/** Like transfer, but moving 0 is allowed and does nothing. */
export function move(c: C, from: Account, to: Account, amount: number): void {
  if (amount < 0) refuse({ kind: "BadAmount" });
  if (amount > 0) transfer(c, from, to, amount);
}''','''/** Internal: like transfer, but moving 0 is allowed and does nothing (even to the same account). */
function moveOrSkip(c: C, from: Account, to: Account, amount: number): void {
  if (amount < 0) refuse({ kind: "BadAmount" });
  if (amount > 0) transfer(c, from, to, amount);
}

/** Like transfer, but moving 0 is allowed and does nothing. Same-account moves are always refused. */
export function move(c: C, from: Account, to: Account, amount: number): void {
  if (amount < 0) refuse({ kind: "BadAmount" });
  if (from === to) refuse({ kind: "SameAccount" });
  moveOrSkip(c, from, to, amount);
}''')
for a in ['move(c, escrow, seller, amount - fee)','move(c, escrow, house, fee)','move(c, escrow, buyer, part)','move(c, escrow, a, part)','move(c, escrow, b, amount - part)','move(c, buyer, seller, amount)']:
    assert a in s; s=s.replace('  '+a,'  moveOrSkip'+a[4:])
open(p,'w').write(s)
t='escrow.test.ts'; s=open(t).read()
s=s.replace('escrow.move(c, "A", "A", 0), "ok", { A: 0 });','escrow.move(c, "A", "A", 0), "SameAccount", { A: 0 });')
open(t,'w').write(s)
EOF
grep -n "moveOrSkip\|move(" escrow.ts; node --test escrow.test.ts 2>&1 | tail -9
